    const MONTH_H = MONTH_HDR + WEEK_HDR + WEEK_ROWS * DAY_H + (WEEK_ROWS - 1) * DAY_GAP + MONTH_PAD;
    const YEAR_W = 2 * YEAR_PAD + 4 * MONTH_W + 3 * MONTH_GAP;
